from __future__ import annotations

import subprocess
from pathlib import Path

EXPECTED_BLOBS = {
    "live_contentops/_eight_platform_substack_first_pipeline_impl_v1.py": "68e65c0249701d7a3185586a82b5cff6d81a491d",
    "live_contentops/native_llm_first_daily_app_supervisor_v1.py": "cd769099d7da1c431f6b6ef755cb7378dd9b56be",
    "live_contentops/daily_app_supervisor_v1.py": "2165099af17bcd554a49de69c7c9bbb4e3339682",
    "live_contentops/native_desktop_production_handoff_v1.py": "4d55a312887abfb3f09d2cfa846347714ebd2fc4",
}


def guard_blobs() -> None:
    for raw_path, expected in EXPECTED_BLOBS.items():
        actual = subprocess.check_output(
            ["git", "hash-object", raw_path], text=True
        ).strip()
        if actual != expected:
            raise SystemExit(f"blob drift: {raw_path}: {actual} != {expected}")


def read(path: str) -> str:
    return Path(path).read_text(encoding="utf-8")


def write(path: str, text: str) -> None:
    Path(path).write_text(text, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected one replacement in {path}, found {count}")
    write(path, text.replace(old, new, 1))


def replace_between(path: str, start: str, end: str, replacement: str) -> None:
    text = read(path)
    start_index = text.find(start)
    if start_index < 0:
        raise SystemExit(f"start marker missing in {path}: {start}")
    end_index = text.find(end, start_index)
    if end_index < 0:
        raise SystemExit(f"end marker missing in {path}: {end}")
    write(path, text[:start_index] + replacement + text[end_index:])


